double vwap(const std::vector<double>& px, const std::vector<double>& qty) {
    // sum of px * qty, divided by the sum of qty; 0 if no shares traded
    return 0;
}

widget.solution:
#include <numeric>
#include <vector>

double vwap(const std::vector<double>& px, const std::vector<double>& qty) {
    double shares = std::accumulate(qty.begin(), qty.end(), 0.0);
    if (shares == 0) {
        return 0;
    }
    double value = std::inner_product(px.begin(), px.end(), qty.begin(), 0.0);
    return value / shares;
}

