#include <algorithm>
#include <vector>

// Order { double price; int qty; long long time; } is supplied
std::vector<Order> sort_book(std::vector<Order> b) {
    // best bid first: higher price, then earlier time
    return b;
}

widget.solution:
#include <algorithm>
#include <vector>

// Order { double price; int qty; long long time; } is supplied
std::vector<Order> sort_book(std::vector<Order> b) {
    std::sort(b.begin(), b.end(), [](const Order& x, const Order& y) {
        if (x.price != y.price) {
            return x.price > y.price;
        }
        return x.time < y.time;
    });
    return b;
}

