widget.solution:
#include <algorithm>
#include <numeric>
#include <vector>

int count_up_days(const std::vector<double>& px) {
    if (px.size() < 2) {
        return 0;
    }
    std::vector<double> d(px.size());
    std::adjacent_difference(px.begin(), px.end(), d.begin());
    return std::count_if(d.begin() + 1, d.end(), [](double x) { return x > 0; });
}

