    std::vector<double> cum(daily.size());
    // running total of the daily P&L, then the largest fall from a running peak
    return 0;
}

widget.solution:
#include <algorithm>
#include <numeric>
#include <vector>

double worst_drawdown(const std::vector<double>& daily) {
    std::vector<double> cum(daily.size());
    std::partial_sum(daily.begin(), daily.end(), cum.begin());
    double peak = 0;
    double worst = 0;
    std::for_each(cum.begin(), cum.end(), [&peak, &worst](double c) {
        peak = std::max(peak, c);
        worst = std::max(worst, peak - c);
    });
    return worst;
}

